// Prépare la charge par secteur : le prompt système porte les règles
// d'interprétation RI0-RI10 (§ 10.4.3), la charge utilisateur est le JSON
// EXACT des métriques du secteur — conservé tel quel pour input_payload,
// sans quoi la fidélité du commentaire serait invérifiable a posteriori.
const runId = $('Ouvrir le run').first().json.run_id;
const SYSTEME = `Tu es la couche de rédaction d'un dispositif de veille économique destiné à un décideur de PME industrielle. Tu reçois un objet JSON de métriques calculées en amont par la base de données : c'est ta SEULE source. Applique dans l'ordre les règles d'interprétation suivantes. RI0, prioritaire sur toutes les autres — interdiction de calcul : ne produis, ne recalcule, n'arrondis et n'extrapole aucune valeur ; reprends les chiffres tels quels ; toute métrique absente ou null est signalée dans « Points à vérifier », sans conclusion — la colonne completude énonce ce qui manque et pourquoi, et tu la REPRENDS TELLE QUELLE : aucune quantité dérivée n'est admise, même triviale (ne calcule pas un nombre de points manquants depuis « 7 sur 12 » — cite « 7 point(s) sur 12 » à l'identique). RI1 — effet de base : si la période de référence paraît atypique, déclare la variation relative peu significative et privilégie le niveau absolu. RI2 — saisonnalité : ne fonde aucune lecture sur variation_periode_pct (périodes consécutives en série brute) ; fonde-la sur glissement_annuel_pct (même période de l'année précédente), ou sur moyenne_mobile_annuelle et ecart_a_la_moyenne_pct ; si les deux sont null, dis-le et abstiens-toi de qualifier l'évolution. RI3 — effets d'anticipation : un pic suivi d'un creux d'ampleur comparable est traité comme un ensemble unique, avec recherche d'une échéance réglementaire ou fiscale en hypothèse. RI4 — matérialité : si la variation est inférieure en valeur absolue à seuil_materialite_pct, déclare-la non significative et ne lui attribue aucune explication. RI5 — fiabilité : si statut_validation n'est ni valide_source ni valide_humain, abaisse d'un niveau la confiance attribuée et motive cet abaissement. RI6 — persistance : n'emploie « tendance » ou « inversion » qu'avec au moins trois périodes cohérentes — si l'historique fourni ne permet pas d'en juger, n'emploie aucun des deux termes. RI7 — volume et structure : si les deux dimensions sont fournies, analyse-les conjointement et signale toute divergence en priorité. RI8 — décomposition : si des segments évoluent en sens opposés, ne présente pas l'agrégat comme représentatif. RI9 — interdiction de causalité : formulations proscrites : « en raison de », « causé par », « s'explique par » ; admises : « concomitant avec », « hypothèse à vérifier », « compatible avec ». RI10 — hypothèses concurrentes : présente toutes les explications compatibles avec les données, chacune accompagnée de la donnée qui permettrait de trancher. Format imposé, 250 mots maximum, en français : Constat / Neutralisations appliquées / Lecture / Hypothèses / Qualification (niveau de signal : routine, à surveiller, significatif, rupture ; niveau de confiance : élevée, moyenne, faible) / Points à vérifier. Arrête-toi au diagnostic : aucune recommandation de décision.`;

const sortie = [];
for (const item of $input.all()) {
  const s = item.json;
  sortie.push({ json: {
    run_id: runId,
    sector_code: s.sector_code,
    charge: s.charge,
    systeme: SYSTEME,
    utilisateur: 'Métriques calculées du secteur « ' + s.sector_code + ' » (seule source autorisée) : ' + JSON.stringify(s.charge)
  } });
}
if (sortie.length === 0) throw new Error('v_dernier_point ne renvoie aucun secteur sur les zones agrégées — vérifier la vue et le filtre de zones.');
return sortie;

// Normalise la réponse du modèle, consigne les échecs. La violation de
// RI0/RI9 se détecte à la relecture humaine — c'est sa fonction — mais un
// contrôle lexical grossier des formulations proscrites est appliqué ici
// pour signalement (jamais pour correction automatique).
const sorties = [];
const incidents = [];
const lignes = $input.all();
for (let i = 0; i < lignes.length; i++) {
  const r = lignes[i].json;
  const t = $('Préparer les charges').itemMatching(i).json;
  if (r.error) { incidents.push(t.sector_code + ' : appel en échec (' + JSON.stringify(r.error).slice(0, 200) + ')'); continue; }
  const texte = r.content?.[0]?.text ?? null;
  if (!texte) { incidents.push(t.sector_code + ' : réponse sans texte'); continue; }
  const proscrites = ['en raison de', 'causé par', 'causée par', "s'explique par"].filter(f => texte.toLowerCase().includes(f));
  sorties.push({ json: {
    run_id: t.run_id,
    sector_code: t.sector_code,
    input_payload: JSON.stringify(t.charge),
    model: 'claude-opus-4-8',
    text: texte,
    _signalement_ri9: proscrites.length ? 'formulations proscrites détectées : ' + proscrites.join(', ') : '',
    _incidents: incidents
  } });
}
if (sorties.length === 0) {
  // Échec bruyant, jamais d'item vide vers l'écriture : le run reste
  // visible en échec et le message porte les incidents réels — la cause,
  // pas son symptôme (constaté le 17.08 : un marqueur sans run_id partait
  // à l'INSERT et la contrainte NOT NULL répondait à la place du vrai motif).
  throw new Error('Aucun commentaire généré. Incidents : ' + (incidents.join(' | ') || 'aucun incident consigné — vérifier l’appariement des items'));
}
return sorties;

parameters.query:
INSERT INTO commentaries (run_id, sector_code, input_payload, model, text)
VALUES ($1, $2, $3::jsonb, $4, $5)
RETURNING commentary_id, sector_code, status;
